      dhead = 112,
      dialog = 1,
      music = "60_Beaytiful_Daily",
      renming = "$u",
      renwu = "npc",
      role1 = 155000,
      role2 = 102101,
      role3 = 102201,
      role5 = 155402,
      sentence = "...That's not what I meant.",
