      music = "60_Beaytiful_Daily",
      renming = "$u",
      renwu = "npc",
      role1 = 155000,
      role2 = 102101,
      role3 = 102201,
      role5 = 155402,
      sentence = "I meant, what were you implying by that? For instance, are you trying to get kids to seize the day? To give it their all?",
