      renwu = "npc",
      role1 = 155000,
      role2 = 102101,
      role3 = 102201,
      role5 = 155402,
      sentence = "Therefore, one shouldn't try to preach to others using overly-objective and idealistic principles.",
      voice = 2,
      next = {18}
    },
    [18] = {
      beijing = 1233,
      dialog = 2,
      idx = 1,
      male = 1,
      music = "60_Beaytiful_Daily",
      renming = "Victor",
      renwu = "npc",
      role1 = 155000,
      role2 = 102101,
      role3 = 102201,
      role5 = 155402,
      sentence = "Giving it one's all is no doubt desirable, and there's no excuse for just giving up entirely.",
      voice = 2,
      next = {19}
    },
    [19] = {
      beijing = 1233,
      dialog = 2,
      idx = 1,
      male = 1,
      music = "60_Beaytiful_Daily",
      renming = "Victor",
      renwu = "npc",
      role1 = 155000,
      role2 = 102101,
      role3 = 102201,
      role5 = 155402,
      sentence = "But that doesn't mean everyone has to work hard and struggle toward some goal all the time. After all, everyone has different expectations of themselves.",
