      dialog = 2,
      idx = 1,
      male = 1,
      music = "60_Beaytiful_Daily",
      renming = "Victor",
      renwu = "npc",
      role1 = 155000,
      role2 = 102101,
      role3 = 102201,
      role5 = 155402,
      sentence = "Not everyone wants to stand at the summit.",
