    },
    [5] = {
      beijing = 4995,
      dialog = 3,
      mask = "blackmask",
      music = "PW_7_MonsterNest",
      renwu = "npc",
      sentence = "As a \"Person of Ill Omen\", I was fated to become a bride for a water ghost of the Rushwater River in order to ward off a flood.",
