    },
    [6] = {
      beijing = 4995,
      dialog = 3,
      mask = "blackmask",
      music = "PW_7_MonsterNest",
      renwu = "npc",
      sentence = "I was born with Yin-Yang Sight—the ability to see creatures of the ghost world—and I had never been liked by my fellow villagers. When I got to be old enough to know better, I left the village as soon as I could.",
      next = {7}
    },
    [7] = {
      beijing = 4995,
      dialog = 3,
      mask = "blackmask",
      music = "PW_7_MonsterNest",
      renwu = "npc",
      sentence = "I roamed the land on my own and used my innate ability to cobble together a reputation as an exorcist. I thought with my newfound skills, I could return to my village with head held high...",
      next = {8}
    },
    [8] = {
      beijing = 4995,
      dialog = 3,
      mask = "blackmask",
      music = "PW_7_MonsterNest",
      renwu = "npc",
      sentence = "Little did I expect, the village was facing a looming flood disaster, and as soon as I returned, I was bound and put into this bridal carriage.",
