      bganim = 2,
      dialog = 3,
      mask = "blackmask",
      music = "PW_7_MonsterNest",
      renwu = "npc",
      sentence = "The sedan shook violently, apparently having been set on the prow of a boat, and I was assisted out of my compartment by the matchmaker.",
