    },
    [2] = {
      beijing = 3711,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "As the proctor's voice sounded from a distance, my hand holding the jug of wine tremored.",
      next = {3}
    },
    [3] = {
      beijing = 3711,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "These past few days, I'd dug up local records from the Northlands, in which was mentioned a local specialty of the Northlands, Lychee Spring wine. And so, I wanted to give it a try.",
      next = {4}
    },
    [4] = {
      beijing = 3711,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "To my chagrin, my first time stealing some wine, I got caught.",
      next = {5}
    },
    [5] = {
      beijing = 3711,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "The pear blossom trees on campus were in full flower. I peered in all directions, then got on my tip toes and stuck the wine jug in one of their branches. However, who would've guessed, a gust of wind blew by, almost knocking down the jug.",
      next = {6}
    },
    [6] = {
      beijing = 3711,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "The proctor's steps were drawing near. I was at a loss for what to do, so I stuck a hand into the flowers and steadied the jug.",
      next = {7}
    },
    [7] = {
      beijing = 3711,
      dhead = 1510,
      dialog = 1,
      music = "PW_1_Relax",
      renming = "$u",
      renwu = "npc",
      sentence = "...!",
      next = {8}
    },
    [8] = {
      beijing = 3711,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "Just as I was flinching in doubt, the proctor had walked up before me. Without wasting many words, he walked right up to the pear blossom tree.",
      next = {9}
    },
    [9] = {
      beijing = 3711,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "But to my surprise, the proctor suddenly made a polite bow and said in an affable tone I'd never heard before:",
      next = {10}
    },
    [10] = {
      beijing = 3711,
      dialog = 2,
      idx = 5,
      music = "PW_1_Relax",
      renming = "Proctor",
      renwu = "npc",
      sentence = "Greetings, Your Highness Crown Prince.",
      next = {11}
    },
    [11] = {
