      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      role1 = 4119000,
      role2 = 4119111,
      role3 = 403203,
      role5 = 4119401,
      ruchang = -1,
      sentence = "Standing under the tree, seemingly out of nowhere, was a man wearing a black robe with a round collar. A pear blossom was resting beside his jade crown.",
      next = {13}
    },
    [13] = {
