      music = "PW_1_Relax",
      renwu = "npc",
      role1 = 4119000,
      role2 = 4119111,
      role3 = 403207,
      role5 = 4119401,
      sentence = "He and I exchanged looks, and his eyes lit up in a smile. I was dazzled by this smile, and only later did it hit me what the proctor had just called him.",
      next = {14}
    },
    [14] = {
      beijing = 3711,
