      renwu = "npc",
      role1 = 4119000,
      role2 = 4119111,
      role3 = 403207,
      role5 = 4119401,
      sentence = "Your Highness Crown Prince — So this was the Crown Prince Gavin, the heir to the East Palace whom everyone said had a bit of a temper.",
      next = {15}
    },
    [15] = {
